import { pathToFileURL } from 'node:url';
import {createRequire} from 'node:module';
import { writeFile, mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
const root='/Users/aantich/dev/oneringai';
const reports: unknown[]=[];
for(const variant of ['source','public','public-cjs'] as const){
 const lib=variant==='source'?await import(pathToFileURL(root+'/src/index.ts').href):variant==='public-cjs'?createRequire(root+'/package.json')('@everworker/oneringai'):await import('@everworker/oneringai');
 const {AgentContextNextGen,InMemoryEvidenceStorage,ObservationMaskingStrategy,StructuredSummaryStrategy,MessageRole,ContentType}=lib;
 const user=(text:string)=>({type:'message',role:MessageRole.USER,content:[{type:ContentType.INPUT_TEXT,text}]});
 const assistant=(text:string)=>({type:'message',role:MessageRole.ASSISTANT,content:[{type:ContentType.OUTPUT_TEXT,text}]});
 for(const sourceCap of [8192,20000]){
  const scope={ownerId:'owner',namespace:'review-starvation-'+sourceCap};
  const storage=new InMemoryEvidenceStorage({scope});
  const raw={answer:'EXACT_REVIEW_VALUE',padding:'Read observation detail. '.repeat(800)};
  const reference=await storage.put({version:1,recordedAt:1,source:{toolName:'lookup',callId:'call',executionId:'exec',arguments:{},principal:{userId:'owner'},effect:'read',status:'succeeded',completion:'settled',startedAt:1,durationMs:1},result:raw});
  const ctx=AgentContextNextGen.create({model:'gpt-4o-mini',userId:'owner',maxContextTokens:7000,responseReserve:128,features:{evidence:true,workingMemory:false,inContextMemory:false},plugins:{evidence:{storage}},compactionStrategy:new ObservationMaskingStrategy({maxSourceTokens:sourceCap})});
  const exactUser='Original exact user constraints. '.repeat(600);
  ctx.addInputItems([user(exactUser),{type:'message',role:MessageRole.ASSISTANT,content:[{type:ContentType.TOOL_USE,id:'call',name:'lookup',arguments:'{}'}]},{type:'message',role:MessageRole.USER,content:[{type:ContentType.TOOL_RESULT,tool_use_id:'call',content:raw,evidence:{version:1,status:'stored',executionId:'exec',reference}}]},user('Recent first.'),assistant('OK.'),user('Recent second.'),assistant('OK.')]);
  const tokenSizes=ctx.getState().conversation.map((item:unknown)=>ctx.estimateItemTokens(item));
  let error;try{await ctx.prepare();}catch(e){error=(e as Error).message;}
  const entries=(await storage.list()).entries;const sources=[];
  for(const e of entries)if(e.toolName==='__context_source__'){const r=await storage.readRecord(e.reference);sources.push((r.result as {items:unknown[]}).items.length);}
  reports.push({variant,case:'source-budget-starvation',sourceCap,tokenSizes,error,applied:ctx.lastPreparation?.compaction?.applied??false,retainedSourceItemCounts:sources,exactUserRetained:JSON.stringify(ctx.getState()).includes(exactUser),rawRetained:JSON.stringify(ctx.getState()).includes(raw.padding)});ctx.destroy();
 }
 for(const mode of ['mask','summary']){
  let helperCallbacks=0;
  const storage=new InMemoryEvidenceStorage({scope:{ownerId:'owner',namespace:'review-noop-'+mode},maxRecords:2});
  const ctx=AgentContextNextGen.create({model:'gpt-4o-mini',userId:'owner',maxContextTokens:2000,responseReserve:128,criticalCompactionThreshold:0.8,features:{evidence:true,workingMemory:false,inContextMemory:false},plugins:{evidence:{storage}},compactionStrategy:mode==='mask'?new ObservationMaskingStrategy():new StructuredSummaryStrategy()});
  ctx.addInputItems([user('Exact unchanged user constraint. '.repeat(130)),user('Recent first.'),assistant('OK.'),user('Recent second.'),assistant('OK.')]);const cycles=[];const unchanged=JSON.stringify(ctx.getState().conversation);
  for(let i=0;i<3;i++){let error;try{await ctx.prepare({summarize:async(request: any)=>{helperCallbacks++;return {summary:{completedWork:[{text:"No narrative can be removed.",sourceIds:[request.reference.id]}],activeWork:[],constraints:[],decisions:[],uncertainties:[],artifacts:[],actionReceipts:[]}};}});}catch(e){error=(e as Error).message;}cycles.push({error,budgetAvailable:error?undefined:ctx.lastPreparation?.budget.available,lastSuccessfulReport:ctx.lastPreparation?.compaction,historyUnchanged:unchanged===JSON.stringify(ctx.getState().conversation),records:(await storage.list()).entries.length});}
  reports.push({variant,case:'known-noop-storage',mode,helperCallbacks,cycles});ctx.destroy();
 }
}
const {ConfigManager}=await import(pathToFileURL(root+'/apps/amos/src/config/ConfigManager.ts').href);
const {ContextCommand}=await import(pathToFileURL(root+'/apps/amos/src/commands/commands/ContextCommand.ts').href);
const {AgentRunner}=await import(pathToFileURL(root+'/apps/amos/src/agent/AgentRunner.ts').href);
const lib=await import('@everworker/oneringai');
const directory=await mkdtemp(join(tmpdir(),'stage07-review-amos-'));
try{
for(const initialStrategy of ['absent','algorithmic'])for(const selected of ['observation-masking','structured-summary']){
 const caseDirectory=join(directory,initialStrategy+'-'+selected);
 const manager=new ConfigManager(caseDirectory);const config=await manager.load();
 if(initialStrategy==='algorithmic')config.contextStrategy='algorithmic';
 if(selected==='structured-summary')config.modelExecution={helpers:{compactor:{connector:'synthetic-compactor',model:'gpt-4o-mini'}}};config.evidence={enabled:true,directory:join(directory,'evidence'),ownerId:'owner',namespace:'amos'};
 const runner=new AgentRunner(config,[],directory);const ctx=lib.AgentContextNextGen.create({model:'gpt-4o-mini',features:{evidence:true,workingMemory:false,inContextMemory:false},plugins:{evidence:{storage:new lib.InMemoryEvidenceStorage({scope:{ownerId:'owner',namespace:'amos'}})}}});
 // Real runner/command/ConfigManager; only the otherwise-unused model transport is synthetic.
 (runner as any).agent={context:ctx,isRunning:()=>false,destroy:()=>ctx.destroy()};
 const app={getAgent:()=>runner,getConfig:()=>manager.get(),updateConfig:(p:unknown)=>manager.update(p),saveConfig:async()=>{throw new Error('review save failure');}};
 const before={configured:manager.get().contextStrategy,runtime:runner.getContextCompaction().strategy};
 const result=await new ContextCommand().execute({app,args:['strategy',selected],rawInput:'/context strategy '+selected} as any);
 const after={configured:manager.get().contextStrategy,runtime:runner.getContextCompaction().strategy};
 await manager.save();const persisted=(await new ConfigManager(caseDirectory).load()).contextStrategy;
 reports.push({case:'amos-failed-persistence',initialStrategy,selected,before,result,after,persistedOnNextSave:persisted});runner.destroy();
}
}finally{await rm(directory,{recursive:true,force:true});}
for(const variant of ['source','public','public-cjs']){
 const rows=reports as any[];
 for(const sourceCap of [8192,20000]){
  const selected=rows.find(r=>r.variant===variant&&r.case==='source-budget-starvation'&&r.sourceCap===sourceCap);
  if(selected.error||!selected.applied||selected.retainedSourceItemCounts[0]!==2||!selected.exactUserRetained||selected.rawRetained)throw new Error('Candidate correction failed');
 }
 for(const mode of ['mask','summary']){
  const noop=rows.find(r=>r.variant===variant&&r.case==='known-noop-storage'&&r.mode===mode);
  if(noop.helperCallbacks||noop.cycles.some((cycle:any)=>cycle.error||cycle.records!==0||!cycle.historyUnchanged||cycle.lastSuccessfulReport?.applied||cycle.lastSuccessfulReport?.helperInvoked||cycle.lastSuccessfulReport?.sourceReferences.length))throw new Error('No-op correction failed');
 }
}
for(const rollback of (reports as any[]).filter(r=>r.case==='amos-failed-persistence')){
 const expected=rollback.initialStrategy==='absent'?undefined:'algorithmic';
 if(rollback.result.success||rollback.after.configured!==expected||rollback.after.runtime!=='algorithmic'||rollback.persistedOnNextSave!==expected)throw new Error('Rollback correction failed');
}
await writeFile('/tmp/oneringai-stage07-fixes-public-reproductions.json',JSON.stringify(reports,null,2)+'\n');console.log(JSON.stringify(reports));

cjs.script:
const fs=require('node:fs'),assert=require('node:assert/strict'),{createRequire}=require('node:module'),esbuild=require('/Users/aantich/dev/oneringai/node_modules/esbuild');
const source=fs.readFileSync('examples/context-strategy-comparison.ts','utf8').replace(/^if \(process\.argv\[1\].*await main\(\);$/m,'');
const transformed=esbuild.transformSync(source,{loader:'ts',format:'cjs',target:'node22'});const mod={exports:{}};
new Function('require','module','exports',transformed.code)(createRequire(process.cwd()+'/package.json'),mod,mod.exports);
(async()=>{const results=[];for(const strategy of ['algorithmic','observation-masking','structured-summary']){const result=await mod.exports.compareContextStrategy(mod.exports.comparisonTasks.development[0],strategy,false);assert.equal(result.passed,true);results.push(result);console.log('Built public CJS',strategy,'passed');}fs.writeFileSync('/tmp/oneringai-stage07-fixes-cjs-results.json',JSON.stringify(results,null,2)+'\n');})().catch(error=>{console.error(error);process.exitCode=1});
